B.bf0=new A.a1("3. TAXA DE SERVI\xc7O & REPASSE",null,B.dR,null,null,null,null,null,null,null,null,null,null)
B.bfK=new A.a1("A plataforma ret\xe9m uma taxa de intermedia\xe7\xe3o e seguran\xe7a de 10% sobre o valor total do chamado, repassando 90% l\xedquido ao prestador do atendimento.",null,B.eP,null,null,null,null,null,null,null,null,null,null)
B.beu=new A.a1("4. PRAZOS E PONTUALIDADE",null,B.dR,null,null,null,null,null,null,null,null,null,null)
B.bfm=new A.a1("O prestador deve cumprir os prazos de deslocamento:\n\u2022 At\xe9 1 km de dist\xe2ncia: chegada em at\xe9 30 minutos.\n\u2022 Acima de 1 km: chegada em at\xe9 1 hora.\nO n\xe3o comparecimento sem justificativa enseja penalidades e cancelamento do chamado.",null,B.eP,null,null,null,null,null,null,null,null,null,null)
B.Yw=new A.y(!0,B.E,null,null,null,null,13,B.u,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null)
B.bdN=new A.a1("5. CANAL SEGURO & PROIBI\xc7\xc3O DE INTERMEDIA\xc7\xc3O EXTERNA",null,B.Yw,null,null,null,null,null,null,null,null,null,null)
B.bgB=new A.a1("\xc9 estritamente proibido trocar contatos externos (n\xfameros de telefone, WhatsApp particular, chaves PIX externas ou redes sociais) pelo chat do aplicativo com o objetivo de negociar fora da plataforma. A infra\xe7\xe3o acarreta o bloqueio imediato e banimento definitivo das contas envolvidas.",null,B.eP,null,null,null,null,null,null,null,null,null,null)
B.beb=new A.a1("6. AVALIA\xc7\xd5ES E CONDUTA",null,B.dR,null,null,null,null,null,null,null,null,null,null)
B.bgE=new A.a1("Todas as partes concordam em agir com respeito m\xfatuo, integridade e profissionalismo. Ao fim de cada atendimento, o cliente realiza a avalia\xe7\xe3o de 1 a 5 estrelas que comp\xf5e a pontua\xe7\xe3o p\xfablica do profissional.",null,B.eP,null,null,null,null,null,null,null,null,null,null)
